const PAGE_JS = "const API_BASE = \"/api/v1\";\nconst results = document.querySelector(\"#results\");\nconst resultCount = document.querySelector(\"#result-count\");\nconst searchInput = document.querySelector(\"#search-input\");\nconst categoryFilter = document.querySelector(\"#category-filter\");\nconst languageFilter = document.querySelector(\"#language-filter\");\nconst countryFilter = document.querySelector(\"#country-filter\");\nconst nearMeButton = document.querySelector(\"#near-me-button\");\nconst nearMeStatus = document.querySelector(\"#near-me-status\");\nlet nearMeCoordinates = null;\n\nfunction escapeHtml(value) {\n  return String(value ?? \"\").replace(/[&<>\"']/g, (char) => ({\n    \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\"\n  })[char]);\n}\n\nfunction safeWebsite(value) {\n  try {\n    const url = new URL(value);\n    return [\"https:\", \"http:\"].includes(url.protocol) ? url.href : null;\n  } catch {\n    return null;\n  }\n}\n\nfunction verificationLabel(status) {\n  if (status === \"verified\") return { label: \"Verified listing\", className: \"verified\" };\n  if (status === \"needs_review\") return { label: \"Needs review\", className: \"review\" };\n  return { label: \"Verification pending\", className: \"pending\" };\n}\n\nfunction resourceCard(resource) {\n  const verification = verificationLabel(resource.verification?.status);\n  const location = [resource.location?.city, resource.location?.region, resource.location?.country]\n    .filter(Boolean).join(\", \");\n  const website = safeWebsite(resource.website_url);\n  const checked = resource.verification?.last_checked_at\n    ? new Date(resource.verification.last_checked_at).toLocaleDateString()\n    : null;\n  const services = Array.isArray(resource.services) ? resource.services.slice(0, 3) : [];\n  return `<article class=\"resource-card\">\n    <span class=\"status-pill ${verification.className}\">${verification.label}</span>\n    <h4>${escapeHtml(resource.name)}</h4>\n    <p>${escapeHtml(resource.description)}</p>\n    <div class=\"resource-meta\">${escapeHtml(location || \"Location not provided\")} · ${escapeHtml(resource.category || \"Support resource\")}</div>\n    ${services.length ? `<div class=\"tag-list\">${services.map((item) => `<span>${escapeHtml(item)}</span>`).join(\"\")}</div>` : \"\"}\n    ${checked ? `<p class=\"checked-date\">Last checked: ${escapeHtml(checked)}</p>` : \"\"}\n    ${website ? `<p class=\"resource-link\"><a href=\"${escapeHtml(website)}\" target=\"_blank\" rel=\"noopener noreferrer\">Visit official website ↗</a></p>` : \"\"}\n  </article>`;\n}\n\nasync function searchResources() {\n  const params = new URLSearchParams({ page: \"1\", limit: \"20\" });\n  if (searchInput.value.trim()) params.set(\"q\", searchInput.value.trim());\n  if (categoryFilter.value) params.set(\"category\", categoryFilter.value);\n  if (languageFilter.value) params.set(\"language\", languageFilter.value);\n  if (countryFilter.value.trim()) params.set(\"country\", countryFilter.value.trim());\n  if (nearMeCoordinates) {\n    params.set(\"lat\", String(nearMeCoordinates.latitude));\n    params.set(\"lng\", String(nearMeCoordinates.longitude));\n    params.set(\"radius_km\", \"25\");\n  }\n  results.innerHTML = '<div class=\"empty-state\"><p>Searching the directory…</p></div>';\n  resultCount.textContent = \"Loading\";\n  try {\n    const response = await fetch(`${API_BASE}/resources?${params.toString()}`, {\n      headers: { Accept: \"application/json\" }\n    });\n    if (!response.ok) throw new Error(\"The directory is temporarily unavailable.\");\n    const payload = await response.json();\n    if (!payload.success) throw new Error(payload.error?.message || \"Search failed.\");\n    const items = Array.isArray(payload.data) ? payload.data : [];\n    const total = payload.pagination?.total ?? items.length;\n    resultCount.textContent = `${total} resource${total === 1 ? \"\" : \"s\"} found`;\n    results.innerHTML = items.length\n      ? items.map(resourceCard).join(\"\")\n      : '<div class=\"empty-state\"><span aria-hidden=\"true\">♡</span><p>No listings matched those filters yet. Try a different search or check back as the directory grows.</p></div>';\n  } catch (error) {\n    resultCount.textContent = \"Unable to load resources\";\n    results.innerHTML = `<div class=\"empty-state\"><p>${escapeHtml(error.message)}</p></div>`;\n  }\n}\n\ndocument.querySelector(\"#search-form\").addEventListener(\"submit\", (event) => {\n  event.preventDefault();\n  searchResources();\n});\n\ndocument.querySelectorAll(\"[data-query]\").forEach((button) => {\n  button.addEventListener(\"click\", () => {\n    searchInput.value = button.dataset.query;\n    categoryFilter.value = \"\";\n    searchResources();\n    document.querySelector(\"#find-help\").scrollIntoView({ behavior: \"smooth\" });\n  });\n});\n\ndocument.querySelector(\"[data-professional-search]\").addEventListener(\"click\", () => {\n  categoryFilter.value = \"professional\";\n  searchResources();\n});\n\nnearMeButton.addEventListener(\"click\", () => {\n  if (nearMeCoordinates) {\n    nearMeCoordinates = null;\n    nearMeButton.textContent = \"Use my location\";\n    nearMeStatus.textContent = \"Nearby filter cleared. No location is being used for this search.\";\n    searchResources();\n    return;\n  }\n  if (!navigator.geolocation) {\n    nearMeStatus.textContent = \"This browser does not support location. You can enter a country or location in the search instead.\";\n    return;\n  }\n  nearMeButton.disabled = true;\n  nearMeStatus.textContent = \"Asking your browser for permission to use your location…\";\n  navigator.geolocation.getCurrentPosition((position) => {\n    nearMeCoordinates = {\n      latitude: position.coords.latitude,\n      longitude: position.coords.longitude\n    };\n    nearMeButton.disabled = false;\n    nearMeButton.textContent = \"Clear nearby filter\";\n    nearMeStatus.textContent = \"Nearby search is on (approximate 25 km area). Coordinates are sent with this search request only and are not saved in your profile.\";\n    searchResources();\n  }, (error) => {\n    const messages = {\n      1: \"Location permission was denied. You can still search by entering a country or location.\",\n      2: \"Your device could not determine its location. Try again or search by country.\",\n      3: \"The location request timed out. Try again or search by country.\"\n    };\n    nearMeStatus.textContent = messages[error.code] || \"We could not get your location.\";\n    nearMeButton.disabled = false;\n  }, { enableHighAccuracy: false, timeout: 12000, maximumAge: 60000 });\n});\n\nconst locationButton = document.querySelector(\"#share-location\");\nconst locationStatus = document.querySelector(\"#location-status\");\nlocationButton.addEventListener(\"click\", () => {\n  if (!(\"geolocation\" in navigator)) {\n    locationStatus.textContent = \"This browser does not support location sharing. If it is an emergency, call your local emergency number and describe your location.\";\n    return;\n  }\n  locationButton.disabled = true;\n  locationStatus.textContent = \"Requesting permission to use your device location…\";\n  navigator.geolocation.getCurrentPosition(async (position) => {\n    const { latitude, longitude, accuracy } = position.coords;\n    const mapUrl = `https://www.google.com/maps?q=${latitude},${longitude}`;\n    const message = `My current location: ${mapUrl} (location accuracy approximately ${Math.round(accuracy)} metres)`;\n    locationStatus.textContent = \"Location found. Choose a person or app to share it with. This directory has not received your coordinates.\";\n    try {\n      if (navigator.share) {\n        await navigator.share({ title: \"My current location\", text: message, url: mapUrl });\n      } else if (navigator.clipboard?.writeText) {\n        await navigator.clipboard.writeText(message);\n        locationStatus.textContent = \"Location link copied. Paste it into a message to your trusted contact or responder.\";\n      } else {\n        locationStatus.replaceChildren();\n        const link = document.createElement(\"a\");\n        link.href = mapUrl;\n        link.target = \"_blank\";\n        link.rel = \"noopener noreferrer\";\n        link.textContent = \"Open your location in Maps\";\n        locationStatus.append(\"Location found. Share this map link with your trusted contact: \", link);\n      }\n    } catch (error) {\n      if (error.name !== \"AbortError\") locationStatus.textContent = \"Your location was found, but sharing was cancelled or unavailable. You can open the map link and share it manually.\";\n    } finally {\n      locationButton.disabled = false;\n    }\n  }, (error) => {\n    const messages = {\n      1: \"Location permission was denied. You can enable it in your browser settings, or call your local emergency number and state your location.\",\n      2: \"Your device could not determine its location. Try again or describe your location to emergency services.\",\n      3: \"The location request timed out. Try again if it is safe to do so.\"\n    };\n    locationStatus.textContent = messages[error.code] || \"We could not get your location. If someone is in immediate danger, call your local emergency number.\";\n    locationButton.disabled = false;\n  }, { enableHighAccuracy: true, timeout: 15000, maximumAge: 10000 });\n});\n\nsearchResources();\n";


const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
  "Access-Control-Max-Age": "86400"
};
function json(data, status) {
  return new Response(JSON.stringify(data), {
    status: status || 200,
    headers: Object.assign({"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"}, CORS_HEADERS)
  });
}
function apiError(message, status, code) {
  return json({success:false,error:{code:code,message:message}},status);
}
function jsonArray(value) {
  if (!value) return [];
  try { const parsed=JSON.parse(value); return Array.isArray(parsed)?parsed.filter(item=>typeof item==="string"):[]; }
  catch (_) { return []; }
}
function serializeResource(row) {
  return {
    id:row.id,name:row.name,description:row.description,website_url:row.website_url,source_url:row.source_url,
    contact:{email:row.email,phone:row.phone},
    location:{address_line:row.address_line,city:row.city,region:row.region,postal_code:row.postal_code,country:row.country,country_code:row.country_code,latitude:row.latitude,longitude:row.longitude},
    category:row.category,services:jsonArray(row.services_json),languages:jsonArray(row.languages_json),
    eligibility:row.eligibility,accessibility:jsonArray(row.accessibility_json),tags:jsonArray(row.tags_json),
    verification:{status:row.verification_status,last_verified_at:row.last_verified_at,last_checked_at:row.last_checked_at},
    created_at:row.created_at,updated_at:row.updated_at
  };
}
function addFilter(clauses,bindings,column,value) {
  if (value && value.trim()) { clauses.push(column+" = ?"); bindings.push(value.trim()); }
}
function boundedInteger(value,fallback,min,max) {
  const parsed=Number.parseInt(value||"",10);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(max,Math.max(min,parsed));
}
async function listResources(url,env) {
  const page=boundedInteger(url.searchParams.get("page"),1,1,1000000);
  const limit=boundedInteger(url.searchParams.get("limit"),20,1,100);
  const offset=(page-1)*limit;
  const clauses=[]; const bindings=[];
  const query=(url.searchParams.get("q")||"").trim();
  if(query){
    const term="%"+query.slice(0,120)+"%";
    clauses.push("(name LIKE ? OR description LIKE ? OR city LIKE ? OR region LIKE ? OR country LIKE ?)");
    bindings.push(term,term,term,term,term);
  }
  addFilter(clauses,bindings,"country",url.searchParams.get("country"));
  addFilter(clauses,bindings,"region",url.searchParams.get("region"));
  addFilter(clauses,bindings,"city",url.searchParams.get("city"));
  addFilter(clauses,bindings,"category",url.searchParams.get("category"));
  addFilter(clauses,bindings,"verification_status",url.searchParams.get("verification_status"));
  const language=(url.searchParams.get("language")||"").trim();
  if(language){clauses.push("EXISTS (SELECT 1 FROM json_each(resources.languages_json) WHERE json_each.value = ?)");bindings.push(language);}
  const service=(url.searchParams.get("service")||"").trim();
  if(service){clauses.push("EXISTS (SELECT 1 FROM json_each(resources.services_json) WHERE json_each.value = ?)");bindings.push(service);}
  const latValue=url.searchParams.get("lat"); const lngValue=url.searchParams.get("lng");
  if(latValue!==null||lngValue!==null){
    const lat=Number(latValue); const lng=Number(lngValue);
    if(!Number.isFinite(lat)||lat < -90||lat > 90||!Number.isFinite(lng)||lng < -180||lng > 180)
      return apiError("Provide valid latitude and longitude for nearby search.",400,"INVALID_LOCATION");
    const radiusValue=Number(url.searchParams.get("radius_km")||"25");
    const radius=Number.isFinite(radiusValue)?Math.min(250,Math.max(1,radiusValue)):25;
    const latDelta=radius/111.32;
    const lngDelta=radius/(111.32*Math.max(Math.abs(Math.cos(lat*Math.PI/180)),0.01));
    clauses.push("latitude IS NOT NULL AND longitude IS NOT NULL AND latitude BETWEEN ? AND ? AND longitude BETWEEN ? AND ?");
    bindings.push(lat-latDelta,lat+latDelta,lng-lngDelta,lng+lngDelta);
  }
  const where=clauses.length?"WHERE "+clauses.join(" AND "):"";
  const countRow=await env.DB.prepare("SELECT COUNT(*) AS total FROM resources "+where).bind(...bindings).first();
  const rows=await env.DB.prepare("SELECT * FROM resources "+where+
    " ORDER BY CASE verification_status WHEN 'verified' THEN 0 WHEN 'pending' THEN 1 ELSE 2 END, name COLLATE NOCASE ASC LIMIT ? OFFSET ?"
  ).bind(...bindings,limit,offset).all();
  const total=countRow?countRow.total:0;
  return json({success:true,data:rows.results.map(serializeResource),pagination:{
    page:page,limit:limit,total:total,total_pages:Math.ceil(total/limit),has_next_page:offset+rows.results.length<total
  }});
}
async function distinctValues(env,sql,bindings) {
  const result=await env.DB.prepare(sql).bind(...(bindings||[])).all();
  return result.results.map(row=>row.value).filter(Boolean);
}
async function handleApi(request,env) {
  const url=new URL(request.url);
  const path=url.pathname.replace(/\/+$/,"")||"/";
  if(request.method==="OPTIONS") return new Response(null,{status:204,headers:CORS_HEADERS});
  if(request.method!=="GET") return apiError("This API currently supports GET requests only.",405,"METHOD_NOT_ALLOWED");
  if(path==="/api/v1/health"){
    try{await env.DB.prepare("SELECT 1").first();return json({success:true,data:{status:"ok",database:"connected",version:"v1"}});}
    catch(_){return apiError("The API is running, but the database is unavailable.",503,"DATABASE_UNAVAILABLE");}
  }
  try{
    if(path==="/api/v1/resources"||path==="/api/v1/search"){
      if(path==="/api/v1/search"&&!(url.searchParams.get("q")||"").trim())
        return apiError("Add a search phrase using the q parameter.",400,"SEARCH_QUERY_REQUIRED");
      return await listResources(url,env);
    }
    if(path==="/api/v1/categories")
      return json({success:true,data:await distinctValues(env,"SELECT DISTINCT category AS value FROM resources ORDER BY category COLLATE NOCASE")});
    if(path==="/api/v1/countries")
      return json({success:true,data:await distinctValues(env,"SELECT DISTINCT country AS value FROM resources ORDER BY country COLLATE NOCASE")});
    if(path==="/api/v1/languages")
      return json({success:true,data:await distinctValues(env,"SELECT DISTINCT value FROM resources, json_each(resources.languages_json) ORDER BY value COLLATE NOCASE")});
    if(path==="/api/v1/locations"){
      const clauses=[];const bindings=[];addFilter(clauses,bindings,"country",url.searchParams.get("country"));
      const where=clauses.length?"WHERE "+clauses.join(" AND "):"";
      const rows=await env.DB.prepare("SELECT DISTINCT city, region, country FROM resources "+where+
        " ORDER BY country COLLATE NOCASE, region COLLATE NOCASE, city COLLATE NOCASE").bind(...bindings).all();
      return json({success:true,data:rows.results});
    }
    const match=path.match(/^\/api\/v1\/resources\/([^/]+)$/);
    if(match){
      const id=decodeURIComponent(match[1]);
      const row=await env.DB.prepare("SELECT * FROM resources WHERE id = ?").bind(id).first();
      if(!row)return apiError("No resource was found with that ID.",404,"RESOURCE_NOT_FOUND");
      return json({success:true,data:serializeResource(row)});
    }
    return apiError("The requested API endpoint does not exist.",404,"NOT_FOUND");
  }catch(cause){
    console.error("API request failed",cause);
    return apiError("Something went wrong while processing your request.",500,"INTERNAL_ERROR");
  }
}



export default {
  async fetch(request,env) {
    const url=new URL(request.url);
    if(!url.pathname.startsWith("/api/")){
      const seo=seoStaticAsset(url.pathname);if(seo)return seo;
      const commonHeaders={
        "X-Content-Type-Options":"nosniff",
        "Referrer-Policy":"strict-origin-when-cross-origin",
        "Cache-Control":"public, max-age=300"
      };
      if(url.pathname==="/"||url.pathname==="/index.html")
        return new Response(PAGE_HTML,{headers:Object.assign({},commonHeaders,{"Content-Type":"text/html; charset=utf-8"})});
      if(url.pathname==="/styles.css")
        return new Response(PAGE_CSS,{headers:Object.assign({},commonHeaders,{"Content-Type":"text/css; charset=utf-8"})});
      if(url.pathname==="/app.js")
        return new Response(PAGE_JS,{headers:Object.assign({},commonHeaders,{"Content-Type":"application/javascript; charset=utf-8"})});
      return new Response("Not found",{status:404,headers:commonHeaders});
    }
    return handleApi(request,env);
  }
};